   * @default co
   */
  area?: CdsArea;
  /** Name der zitierten Person. */
  name: string;
  /** Zitattext. */
  quote: string;
  /**
   * Rolle/Funktion der zitierten Person (leer = keine Rollenzeile im Footer).
   *
   * @default ''
   */
  roleLabel?: string;
}
